def round_half_to_even(n):
    try:
        n = float(n)
        if n.is_integer():
            return int(n)
        elif abs(n - round(n)) == 0.5:
            return round(n) if n % 2 == 0 else round(n) + 1
        else:
            return round(n)
    except (TypeError, ValueError):
        raise ValueError("Input must be a number")

