def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not name or not isinstance(name, str):
        raise ValueError("Name must be a non-empty string")

    if not fields or not isinstance(fields, list):
        raise ValueError("Fields must be a non-empty list")

    for field in fields:
        if not isinstance(field, str):
            raise ValueError("Fields must be strings")

    if not srid_map or not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a non-empty dictionary")

    for key, value in srid_map.items():
        if not isinstance(key, str) or not isinstance(value, int):
            raise ValueError("SRID map keys must be strings and values must be integers")

    # Define the Point subclass dynamically
    Point = type(name, (object,), {
        "__init__": lambda self, *args, **kwargs: None,
        "__repr__": lambda self: f"{name}({', '.join([str(getattr(self, field)) for field in fields])})"
    })

    # Add fields as attributes to the Point subclass
    for field in fields:
        setattr(Point, field, None)

    # Add SRID map to the Point subclass
    Point.srid_map = srid_map

    return Point

