import functools
import threading

class Memoize:
    def __init__(self, cache, key, lock):
        self.cache = cache
        self.key = key
        self.lock = lock if lock else threading.Lock()

    def __call__(self, func):
        @functools.wraps(func)
        def memoized_func(*args, **kwargs):
            current_key = self.key(func, args, kwargs)
            with self.lock:
                if current_key not in self.cache:
                    self.cache[current_key] = func(*args, **kwargs)
                return self.cache[current_key]
        return memoized_func

def hashkey(func, args, kwargs):
    return hash((func, args, tuple(sorted(kwargs.items()))))

def cached(cache, key=hashkey, lock=None):
    return Memoize(cache, key, lock)

