import functools
from collections import OrderedDict, defaultdict

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if not isinstance(maxsize, int) or maxsize <= 0:
                raise ValueError("maxsize must be a positive integer")

            cache = defaultdict(int)
            frequency_dict = defaultdict(OrderedDict)
            least_frequent = 1
            key_len = len(args) + len(kwargs)

            if typed:
                def key_fn(*args, **kwargs):
                    return (func.__qualname__, args, tuple(sorted(kwargs.items())))
            else:
                def key_fn(*args, **kwargs):
                    return (func.__qualname__, tuple(args), tuple(sorted(kwargs.items())))

            def touch(key):
                nonlocal least_frequent
                cache[key] += 1
                frequency_dict[cache[key]][key] = args, kwargs
                if key in frequency_dict[cache[key] - 1]:
                    del frequency_dict[cache[key] - 1][key]
                    if not frequency_dict[cache[key] - 1]:
                        least_frequent = cache[key]

            def make_cache_space():
                nonlocal least_frequent
                while True:
                    if frequency_dict[least_frequent]:
                        break
                    least_frequent += 1
                key = next(iter(frequency_dict[least_frequent]))
                del frequency_dict[least_frequent][key]
                del cache[key]

            if key_len > maxsize:
                make_cache_space()

            try:
                key = key_fn(*args, **kwargs)
            except TypeError:
                del decorator.cache
                return func(*args, **kwargs)

            if key in cache and cache[key] >= least_frequent:
                return frequency_dict[cache[key]][key][0](*frequency_dict[cache[key]][key][1])

            make_cache_space()

            result = func(*args, **kwargs)
            touch(key)
            frequency_dict[1][key] = args, kwargs

            if len(cache) > maxsize:
                make_cache_space()

            return result

        return wrapper

    return decorator

