def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    graph = {cls: set() for cls in classes}
    for i, cls1 in enumerate(classes):
        for cls2 in classes[i+1:]:
            if cls1 in cls2.__mro__:
                graph[cls1].add(cls2)
            elif cls2 in cls1.__mro__:
                graph[cls2].add(cls1)

    indegree = {cls: 0 for cls in graph}
    for cls in graph:
        for neighbor in graph[cls]:
            indegree[neighbor] += 1

    queue = [cls for cls in graph if indegree[cls] == 0]
    result = []

    while queue:
        current = queue.pop(0)
        result.append(current)
        for neighbor in graph[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return result

