def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr.is_binary_expression:
            if expr.operator == '&':
                if expr.left == expr.right:
                    return expr.left
                elif expr.left.is_binary_expression and expr.left.operator == '|':
                    if expr.left.left == expr.right:
                        return expr.left.left
                    elif expr.left.right == expr.right:
                        return expr.left.right
            elif expr.operator == '|':
                if expr.left == expr.right:
                    return expr.left
                elif expr.left.is_binary_expression and expr.left.operator == '&':
                    if expr.left.left == expr.right:
                        return expr.left.left
                    elif expr.left.right == expr.right:
                        return expr.left.right
        return expr

    def apply_negative_absorption(expr):
        if expr.is_binary_expression:
            if expr.operator == '&':
                if expr.left.is_binary_expression and expr.left.operator == '|':
                    if expr.left.left == expr.right:
                        return apply_absorption(expr.right)
                elif expr.left.is_binary_expression and expr.left.operator == '&':
                    if expr.left.right == expr.right:
                        return apply_absorption(expr.right)
            elif expr.operator == '|':
                if expr.left.is_binary_expression and expr.left.operator == '&':
                    if expr.left.left == expr.right:
                        return apply_absorption(expr.right)
                elif expr.left.is_binary_expression and expr.left.operator == '&':
                    if expr.left.right == expr.right:
                        return apply_absorption(expr.right)
        return expr

    result = []
    for arg in args:
        absorbed_arg = apply_absorption(arg)
        negative_absorbed_arg = apply_negative_absorption(absorbed_arg)
        result.append(negative_absorbed_arg)
    return result

