def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Args:
        pieces (list of str): The version pieces to render.
        style (str): The style to render the version pieces into.

    Returns:
        str: The rendered string.

    Raises:
        ValueError: If an invalid style is provided.
    """
    if style == "dotted":
        return '.'.join(pieces)
    elif style == "hyphenated":
        return '-'.join(pieces)
    elif style == "uppercase":
        return '-'.join(pieces).upper()
    elif style == "lowercase":
        return '-'.join(pieces).lower()
    else:
        raise ValueError(f"Invalid style '{style}' provided. Supported styles are 'dotted', 'hyphenated', 'uppercase', and 'lowercase'.")

