def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string cannot be empty")

    if size.isdigit():
        return int(size)

    last_char = size[-1].upper()
    if last_char.isdigit():
        raise ValueError("Invalid size format")

    value = int(size[:-1])
    if last_char == 'K':
        return value * 1024
    elif last_char == 'M':
        return value * 1024 * 1024
    elif last_char == 'G':
        return value * 1024 * 1024 * 1024
    elif last_char == 'T':
        return value * 1024 * 1024 * 1024 * 1024
    elif last_char == 'P':
        return value * 1024 * 1024 * 1024 * 1024 * 1024
    elif last_char == 'E':
        return value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif last_char == 'Z':
        return value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif last_char == 'Y':
        return value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError(f"Unsupported size unit: {last_char}")

