from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not 0 <= number < len(alphabet):
        raise ValueError("Number is out of the range of the alphabet")
    if padding is not None and not (0 <= padding <= len(alphabet)):
        raise ValueError("Padding is out of the range of the alphabet")

    result = []
    while number > 0:
        number, remainder = divmod(number, len(alphabet))
        result.append(alphabet[remainder])

    if padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

