import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Ensure commands is a list if it's a single command
    if not isinstance(commands, list):
        commands = [commands]

    # Ensure args is a list if it's a single argument
    if not isinstance(args, list):
        args = [args]

    # Combine commands and args
    full_command = [commands[0]] + args

    # Initialize subprocess args
    subprocess_args = {
        'args': full_command,
        'cwd': cwd,
        'env': env or {}
    }

    # Hide stderr if requested
    if hide_stderr:
        subprocess_args['stderr'] = subprocess.DEVNULL
    else:
        if verbose:
            subprocess_args['stdout'] = subprocess.PIPE
            subprocess_args['stderr'] = subprocess.STDOUT

    try:
        # Run the command
        result = subprocess.run(**subprocess_args, check=True, text=True)

        # Return the combined stdout and stderr if verbose
        if verbose:
            return result.stdout

        # Return None if not verbose
        return None

    except subprocess.CalledProcessError as e:
        if verbose:
            return f"Error: {e.stderr}"
        else:
            raise subprocess.CalledProcessError(e.returncode, e.cmd, e.output, e.stderr)

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {e.filename}")

    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

