import datetime

class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not isinstance(ticks, int) or not (0 <= ticks < 86400000000000):
            raise ValueError("ticks must be an integer in the range 0 <= ticks < 86400000000000")

        seconds = ticks // 1000000000
        microseconds = ticks % 1000000000

        if tz is None:
            return cls(datetime.datetime(1970, 1, 1, 0, 0, 0) + datetime.timedelta(seconds=seconds, microseconds=microseconds))
        else:
            return cls(datetime.datetime(1970, 1, 1, 0, 0, 0, tzinfo=tz) + datetime.timedelta(seconds=seconds, microseconds=microseconds))

    def __init__(self, dt):
        self._dt = dt

    @property
    def hour(self):
        return self._dt.hour

    @property
    def minute(self):
        return self._dt.minute

    @property
    def second(self):
        return self._dt.second

    @property
    def microsecond(self):
        return self._dt.microsecond

    @property
    def tzinfo(self):
        return self._dt.tzinfo

