        raise ValueError("The number of field names must match the dimension of the result")

    points = []
    for bin_ in hist.bins:
        value = make_value(bin_)
        if isinstance(value, tuple):
            if len(value) != len(field_names):
                raise ValueError("make_value returned a tuple with an incorrect number of elements")
            point = dict(zip(field_names, value))
        else:
            point = {field_names[0]: bin_.bin_center, field_names[1]: value}

        points.append(point)

    return points

