def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide the interface {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        raise zope.interface.Invalid(f"Candidate is missing required methods: {missing_methods}")

    invalid_methods = []
    for method in required_methods.intersection(candidate_methods):
        candidate_method = getattr(candidate, method)
        if not callable(candidate_method):
            invalid_methods.append(f"Method '{method}' is not callable")
        else:
            candidate_signature = candidate_method.__signature__
            required_signature = iface[method].__signature__
            if candidate_signature != required_signature:
                invalid_methods.append(f"Method '{method}' has incorrect signature: {candidate_signature} instead of {required_signature}")

    if invalid_methods:
        if len(invalid_methods) == 1:
            raise zope.interface.Invalid(invalid_methods[0])
        else:
            raise zope.interface.Invalid(", ".join(invalid_methods))

    candidate_attributes = set(dir(candidate))
    required_attributes = set(iface.attributes.keys())

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        raise zope.interface.Invalid(f"Candidate is missing required attributes: {missing_attributes}")

    return True

