def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise ValueError("Input must be a string")

    if not tag:
        return False

    # Check for invalid characters
    if not tag.isalnum() and not any(char in '-_' for char in tag):
        return False

    # Check for leading or trailing hyphens or underscores
    if tag.startswith(('-', '_')) or tag.endswith(('-', '_')):
        return False

    # Check for consecutive hyphens or underscores
    if '--' in tag or '__' in tag:
        return False

    return True

