import json
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    try:
        # Attempt to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, assume it is XRD
        lines = document.strip().splitlines()
        webfinger_dict = {}
        for line in lines:
            if line.startswith('<link rel="acct" href="https://'):
                parts = line.split('"')
                webfinger_dict['acct'] = parts[-2]
                break

        return webfinger_dict

    except Exception as e:
        print(f"Error parsing document: {e}")
        return {}

